--
-- Name: v_ultimo_preco; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_ultimo_preco AS
 SELECT DISTINCT ON (ean, loja) ean,
    loja,
    preco_original,
    moeda,
    custo_total_eur,
    registado_em
   FROM public.historico_precos
  ORDER BY ean, loja, registado_em DESC;


--
-- Name: v_melhor_loja; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_melhor_loja AS
 SELECT p.ean,
    p.titulo,
    m.loja AS melhor_loja,
    m.custo_total_eur AS melhor_custo,
    pt.custo_total_eur AS custo_pt,
    round((((pt.custo_total_eur - m.custo_total_eur) / pt.custo_total_eur) * (100)::numeric), 2) AS poupanca_pct
   FROM ((public.produtos p
     JOIN LATERAL ( SELECT u.loja,
            u.custo_total_eur
           FROM public.v_ultimo_preco u
          WHERE (u.ean = p.ean)
          ORDER BY u.custo_total_eur
         LIMIT 1) m ON (true))
     LEFT JOIN public.v_ultimo_preco pt ON (((pt.ean = p.ean) AND (pt.loja = 'PT'::bpchar))));


